  certHeading: ["Heading text", "Tekst nagłówka", "Text titlu", "سرخی کا متن", "ਸਿਰਲੇਖ ਦੀ ਲਿਖਤ", "শিরোনামের লেখা", "نص العنوان", "Texto do título", "Texto del encabezado", "Texte du titre", "Testun y pennawd"],
  certShowScore: ["Show score", "Pokaż wynik", "Afișează scorul", "اسکور دکھائیں", "ਸਕੋਰ ਦਿਖਾਓ", "স্কোর দেখান", "إظهار الدرجة", "Mostrar pontuação", "Mostrar puntuación", "Afficher le score", "Dangos y sgôr"],
