  bbAccName: ["Account name", "Nazwa konta", "Numele contului", "اکاؤنٹ کا نام", "ਖਾਤੇ ਦਾ ਨਾਮ", "অ্যাকাউন্টের নাম", "اسم الحساب", "Nome da conta", "Nombre de la cuenta", "Nom du compte", "Enw’r cyfrif"],
  bbSort: ["Sort code", "Kod sortowania", "Sort code", "سورٹ کوڈ", "ਸੌਰਟ ਕੋਡ", "সর্ট কোড", "رمز الفرز (Sort code)", "Sort code", "Sort code", "Sort code", "Cod didoli"],
